43	export function makeGithub({
44	  clock,
45	  repo = 'o/r',
46	  issues = [],
47	  pulls = [],
48	  labels = [],
49	  collaborators = {},
50	  variables = {},
51	  branches = {},
52	  commits = {},
53	  trees = {},
54	  releases = null,
55	  runsBySha = {},
56	} = {}) {
57	  const nowMs = () => (clock ? clock.ms() : 0);
58	  const nowIso = () => new Date(nowMs()).toISOString();
59	
60	  const state = {
61	    repo,
62	    issues: issues.map((i) => ({
63	      comments: [], state: 'open', labels: [], body: '', title: '',
64	      created_at: nowIso(), updated_at: nowIso(), ...i,
65	    })),
66	    pulls: pulls.map((p) => ({ comments: [], state: 'open', merged: false, ...p })),
67	    labelDefs: new Map(labels.map((l) => [l.name, { ...l }])),
68	    collaborators: { ...collaborators },
69	    variables: { ...variables },
70	    branches: { ...branches },
71	    commits: { ...commits },
72	    trees: { ...trees },
73	    releases,
74	    runsBySha: { ...runsBySha },
75	    // Every `workflow_dispatch` this repo accepted, in order — `actions.mjs`
76	    // turns each into a run, and a scenario counting billed invocations reads
77	    // the ledger there rather than this raw list.
78	    dispatches: [],
79	    // Every transport call, as "METHOD path". The port's own operations record
80	    // here too, so an API-call budget is countable whichever surface was used.
81	    calls: [],
82	    commentSeq: 100,
83	  };
84	
85	  // Faults, each off until a scenario turns it on.
86	  const faults = {
87	    rateLimited: 0,        // calls remaining that answer 403
88	    hidden: new Set(),     // issue numbers a list read cannot see yet
89	    tearNextSwap: false,   // the next swapLabel's add fails after its remove lands
90	    dropNextLabeled: false, // the next `labeled` webhook never arrives
91	    unknownLabels422: false, // applying an undefined label 422s, as GitHub does
92	    refuseCreateTitled: null, // the next POST /issues with this exact title fails
93	    unreadable: new Set(),    // issue numbers whose direct read answers 500
94	  };
95	
96	  const RATE_LIMITED = () => ({
97	    status: 403,
98	    json: { message: 'API rate limit exceeded', documentation_url: 'https://docs.github.com/rest' },
99	  });
100	
101	  // Charged once per call on EITHER surface, so a scenario's budget counts what
102	  // the code actually spends.
103	  const charge = (label) => {
104	    state.calls.push(label);
105	    if (faults.rateLimited > 0) { faults.rateLimited -= 1; return RATE_LIMITED(); }
106	    return null;
107	  };
108	
109	  // --- store primitives ---------------------------------------------------
110	
111	  const issue = (n) => state.issues.find((i) => i.number === Number(n)) ?? null;
112	  const pull = (n) => state.pulls.find((p) => p.number === Number(n)) ?? null;
113	  const nextNumber = () => Math.max(0, ...state.issues.map((i) => i.number), ...state.pulls.map((p) => p.number)) + 1;
114	  const touch = (i) => { i.updated_at = nowIso(); };
115	
116	  const visible = (i) => !faults.hidden.has(i.number);
117	
118	  function newIssue({ title = '', body = '', labels: want = [] }) {
119	    const it = {
120	      number: nextNumber(), title, body, labels: [...want], state: 'open',
121	      created_at: nowIso(), updated_at: nowIso(), comments: [],
122	    };
123	    state.issues.push(it);
124	    return it;
125	  }
126	
127	  function postComment(target, body) {
128	    const c = { id: (state.commentSeq += 1), body, created_at: secondIso(nowMs()) };
129	    target.comments.push(c);
130	    if (target.updated_at !== undefined) touch(target);
131	    announce({ kind: 'comment', issue: target.number, body, id: c.id, at: nowMs() });
132	    return c;
133	  }
134	
135	  function addLabelTo(i, name) {
136	    if (faults.unknownLabels422 && !state.labelDefs.has(name)) {
137	      return { status: 422, json: { message: 'Label does not exist' } };
138	    }
139	    if (!i.labels.includes(name)) i.labels.push(name);
140	    touch(i);
141	    announce({ kind: 'addLabel', issue: i.number, name, at: nowMs() });
142	    return { status: 200, json: i.labels.map((n) => ({ name: n })) };
143	  }
144	
145	  function removeLabelFrom(i, name) {
146	    const had = i.labels.includes(name);
147	    i.labels = i.labels.filter((l) => l !== name);
148	    touch(i);
149	    // An already-absent label 404s; that is the desired end state, and the real
150	    // port treats it as success.
151	    return had ? { status: 200, json: [] } : { status: 404, json: { message: 'Label does not exist' } };
152	  }
153	
154	  // --- the transport ------------------------------------------------------
155	  //
156	  // One router, matched most-specific first: `/issues/comments/{id}` and
157	  // `/issues/{n}/comments` both have to beat `/issues/{n}`.
158	
159	  // How many requests this fake has served, as the real port counts them: every
160	  // call through the transport, a rate-limited refusal included, because a run
161	  // that spent its budget on refusals spent it.
162	  let apiCalls = 0;
163	
164	  async function route(path, { method = 'GET', body } = {}) {
165	    apiCalls += 1;
166	    const limited = charge(`${method} ${path}`);
167	    if (limited) return limited;
168	    const bare = path.split('?')[0];
169	    let m;
170	
171	    if ((m = /^\/repos\/[^/]+\/[^/]+\/issues\/comments\/(\d+)$/.exec(bare))) {
172	      const id = Number(m[1]);
173	      for (const holder of [...state.issues, ...state.pulls]) {
174	        const c = holder.comments.find((x) => x.id === id);
175	        if (!c) continue;
176	        if (method === 'PATCH') c.body = body.body;
177	        return { status: 200, json: c };
178	      }
179	      return { status: 404, json: null };
180	    }
