53	// The scheduler run owns the executing-leash reclaim because it is deterministic and
54	// hourly, which recovers a dead executor's item in ~2h rather than the janitor's
55	// ~25h (PRINCIPLES.md, owner decision 6).
56	export { EXECUTING_LEASH_MS };
57	
58	const ms = (t) => (t == null ? null : new Date(t).getTime());
59	
60	// The ops `planSchedulerRun` emits, each a label-and-body mechanic the shell applies:
61	//   { kind: 'dedupe',  issue, reason }            close, task:obsolete
62	//   { kind: 'create',  pack, task, labels, body } a task's standing item
63	//   { kind: 'ready',   issue }                    task:blocked -> task:ready
64	//   { kind: 'reclaim', issue, reason }            task:executing -> task:ready
65	//   { kind: 'adopt',   request, title, body, … }  a marked issue becomes an item
66	//   { kind: 'supersede', issue, request, reason } a parked prior run of a re-ask
67	//   { kind: 'retire-orphan', issue, reason }      a standing item whose task is gone closes
68	//
69	// Beside the ops, `asked`: one `{ task, verdict, reason }` per task this run asked,
70	// `verdict` being `go`, `no` or `fail-open` — the run's log, and the whole record
71	// of a decline, since nothing durable is written for one.
72	//
73	// `items` is every `[claudinite-work]` issue the shell fetched (state=all back to
74	// the run-history horizon, open for the rest), each `{ number, title, body, state,
75	// labels, created_at, closed_at, updated_at }`. `stateOf(number)` answers the
76	// state of a `Blocked-by` target that may not be a work item at all; an unknown
77	// number is never treated as closed, so an unreadable blocker delays rather than
78	// releases (the convergence-not-prevention posture).
79	//
80	// `evaluate(task)` is the ask: async, returning the precondition's verdict `{
81	// run, reason, … }` or `{ error }` where the scheduler could not decide — a
82	// missing credential, a failed signal read, a throwing term. An error FAILS OPEN:
83	// the item is created and the executor, which holds the credentials, decides at
84	// pick. It is REQUIRED wherever a task is asked — a fixture with no seam and a
85	// task to ask is a fixture that has not said what the task answers.
86	export async function planSchedulerRun({
87	  tasks, items = [], requests = [], now, schedule, executingLeashMs = EXECUTING_LEASH_MS,
88	  stateOf = () => null, evaluate = null,
89	}) {
90	  const nowMs = ms(now);
91	  const ops = [];
92	  const asked = [];
93	  // REPO SHAPE IS NOT A PRECONDITION (docs/PRINCIPLES.md). "This repo ships the store pipeline", "this repo is a canon
94	  // home with a fleet token" are facts adoption settled, not questions worth
95	  // re-asking every tick — so a repo that carries a pack but not one task's
96	  // subject names that task in `taskScheduler.disabledTasks` and it is never
97	  // asked. Read here rather than at pick, because the cheapest run is the one
98	  // that files no item at all.
99	  const disabled = new Set(schedule?.disabledTasks ?? []);
100	  const closedByThisRun = new Set();
101	
102	  // ---- the orphan reap ----------------------------------------------------
103	  // A blocked standing item whose `<pack>/<task>` is not declared at HEAD can
104	  // never execute — job 1 matches its family title-exact on the declared id, so a
105	  // legacy pack spelling is invisible to it, and job 2 would otherwise ready the
106	  // item at its Not-before and hand an executor a task path that is not on disk.
107	  // Guarded on a non-empty task list so an unreadable declaration reaps nothing,
108	  // and scoped to BLOCKED so nothing in flight is touched — a ready orphan is
109	  // picked within the tick and parks for a human, which is visible rather than
110	  // silent. Items waiting on a blocker are untouched: they are somebody's
111	  // dependency, not a schedule's.
112	  const byId = new Map(tasks.map((t) => [`${t.pack}/${t.id}`, t]));
113	  for (const item of items) {
114	    if (item.state !== 'open' || !isStatus(item, STATUS_BLOCKED) || !tasks.length) continue;
115	    const parsed = parseWorkItemTitle(item.title);
116	    if (!parsed || parsed.qualifier !== null) continue;
117	    const key = `${parsed.pack}/${parsed.task}`;
118	    if (parseWorkItemBody(item.body).blockedBy.length) continue;
119	    if (byId.has(key) && !disabled.has(key)) continue;
120	    closedByThisRun.add(item.number);
121	    ops.push({
122	      kind: 'retire-orphan', issue: item.number, pack: parsed.pack, task: parsed.task,
123	      reason: disabled.has(key)
124	        ? `Closing: \`${key}\` is named in this repository's \`taskScheduler.disabledTasks\`, so it is not `
125	          + 'asked here. Remove it from that list to bring the task back.'
126	        : `Closing: \`${key}\` is no longer declared on this repository, so this item names a task `

