1	// THE FAKE CLOCK — virtual time and the ordered event queue every other fake
2	// module schedules on.
3	//
4	// It stands in for `src/world/clock.mjs`, so `port` carries exactly that
5	// module's names and nothing else; everything a scenario drives the clock WITH
6	// hangs off the harness object beside it. That split is what lets the parity
7	// guard compare key sets — a port that also carried `runUntil` could never be
8	// compared against the real one — and it is the shape every module in this
9	// folder takes.
10	//
11	// Time moves only when an event fires or a scenario advances it. There is no
12	// wall clock here at all — no `setTimeout`, no `Date.now()` — so a run is
13	// deterministic and a scenario spanning a fortnight costs microseconds.
14	//
15	// ORDERING IS TOTAL: strictly by instant, FIFO within a tie. Two events booked
16	// for the same instant fire in the order they were booked, which is what lets a
17	// scenario WRITE a race rather than hope for one.
18	
19	const at_ = (when) => (typeof when === 'number' ? when : Date.parse(when));
20	
21	export const MINUTE = 60_000;
22	export const HOUR = 60 * MINUTE;
23	export const DAY = 24 * HOUR;
24	
25	export function makeClock({ start = '2026-08-12T00:00:00Z' } = {}) {
26	  let t = at_(start);
27	  let seq = 0;
28	  const queue = [];
29	
30	  const port = {
31	    now: () => new Date(t),
32	    nowMs: () => t,
33	    nowIso: () => new Date(t).toISOString(),
34	  };
35	
36	  // Book `fn` at an absolute instant. An instant already past is booked at the
37	  // current one rather than dropped: a fake that silently "missed" it would be
38	  // modelling a platform behaviour nobody asked for.
39	  const at = (when, fn) => { queue.push({ t: Math.max(at_(when), t), seq: seq++, fn }); return harness; };
40	  const after = (deltaMs, fn) => at(t + deltaMs, fn);
41	
42	  // Fire every event strictly before `to`, then park the clock AT `to`. Events
43	  // beyond it SURVIVE for a later segment — a scenario runs in phases to assert
44	  // a mid-state, and a queue emptied at each boundary would lose them.
45	  //
46	  // Each event is AWAITED. The code the harness drives is async throughout, and
47	  // a synchronous drain would let the next instant's event run while the last
48	  // one's promise was still settling — virtual time going backwards, silently,
49	  // exactly where a scenario is asserting an ordering.
50	  const runUntil = async (to) => {
51	    const end = at_(to);
52	    for (;;) {
53	      queue.sort((a, b) => a.t - b.t || a.seq - b.seq);
54	      if (!queue.length || queue[0].t >= end) break;
55	      const ev = queue.shift();
56	      t = ev.t;
57	      await ev.fn();
58	    }
59	    t = end;
60	    return harness;
61	  };
62	
63	  const harness = {
64	    port,
65	    at,
66	    after,
67	    runUntil,
68	    // The instant, for a scenario computing one rather than reading it back off
69	    // an artifact.
70	    ms: () => t,
71	    iso: () => port.nowIso(),
72	    // How much has not fired yet: what a scenario asserting "nothing is left"
73	    // reads, instead of reaching into the array.
74	    pending: () => queue.length,
75	  };
76	  return harness;
77	}

1	// The fake world, driven — the six modules composing into one runnable world.
2	//
3	// Every case here is about a behaviour the fake OWNS, never about a value it
4	// was handed: the orderings the clock guarantees, the GitHub limitations the
5	// mechanism is designed around, and the shape of a session's life. A scenario
6	// suite that trusts the harness needs those proven somewhere, and this is the
7	// only file whose subject they are.
