34	test('events fire strictly by instant, and in booking order within one instant', async () => {
35	  const { clock } = world();
36	  const seen = [];
37	  clock.at('2026-08-12T02:00:00Z', () => seen.push('later'));
38	  clock.at('2026-08-12T01:00:00Z', () => seen.push('first-booked-at-01'));
39	  clock.at('2026-08-12T01:00:00Z', () => seen.push('second-booked-at-01'));
40	  await clock.runUntil('2026-08-12T03:00:00Z');
41	  assert.deepEqual(seen, ['first-booked-at-01', 'second-booked-at-01', 'later']);
42	});
43	
44	// A scenario runs in phases to assert a mid-state. An event beyond the segment
45	// must SURVIVE it — a queue drained at each boundary would lose the second half
46	// of every scenario written that way.
47	test('an event beyond the segment survives for the next one', async () => {
48	  const { clock } = world();
49	  const seen = [];
50	  clock.at('2026-08-12T05:00:00Z', () => seen.push('late'));
51	  await clock.runUntil('2026-08-12T03:00:00Z');
52	  assert.deepEqual(seen, []);
53	  assert.equal(clock.iso(), '2026-08-12T03:00:00.000Z', 'the clock parks at the boundary');
54	  await clock.runUntil('2026-08-12T06:00:00Z');
55	  assert.deepEqual(seen, ['late']);
56	});
