58	// The harness drives async code throughout, so a segment that returned before
59	// an event's promise settled would let the next instant run inside the last —
60	// virtual time going backwards exactly where an ordering is being asserted.
61	test('an async event is awaited before the next instant runs', async () => {
62	  const { clock } = world();
63	  const seen = [];
64	  clock.at('2026-08-12T01:00:00Z', async () => {
65	    await Promise.resolve();
66	    seen.push('slow');
67	  });
68	  clock.at('2026-08-12T02:00:00Z', () => seen.push('after'));
69	  await clock.runUntil('2026-08-12T03:00:00Z');
