73	// --- the GitHub limitations the mechanism is built around ----------------
74	
75	// The pair claim arbitration depends on: ids order totally, timestamps do not.
76	test('comment ids strictly increase while timestamps tie at one second', async () => {
77	  const { clock, github } = world({ issues: [{ number: 1, title: 't', labels: [] }] });
78	  await github.port.comment(null, REPO, 1, 'first');
79	  clock.at(clock.ms() + 400, () => {});
80	  await clock.runUntil(clock.ms() + 401);
81	  await github.port.comment(null, REPO, 1, 'second');
82	  const [a, b] = github.find(1).comments;
83	  assert.ok(b.id > a.id, `${b.id} must be above ${a.id}`);
84	  assert.equal(a.created_at, b.created_at, 'under a second apart, the two tie on time');
