// THE HOLDER'S SIGN OF LIFE (docs/PRINCIPLES.md).
// A work step is the work: it may legitimately run for hours, and while it does
// the item goes dark and the executing leash cannot tell it from a dead runner.
// So the executor comments on its own item at a fixed interval, and the scheduler run's
// reclaim measures silence from THAT rather than from a run-length cap.
//
// One mechanism, two things it buys: long work becomes legal (the run cap that
// held the leash arithmetic together retires), and the item's timeline stays live
// through work nobody can otherwise see.
//
// WHAT COUNTS AS ACTIVITY IS THE HOLDER'S OWN SIGNAL, never the issue's
// `updated_at` (#924). Any comment moves `updated_at` — including one written by
// an executor that LOST the claim race and let go — so a clock read off the issue
// defers the reclaim of an item nobody is working on. The struck claims a lost
// race leaves behind carry the episode marker, and are excluded here for exactly
// that reason.

import { nowMs } from '../world/clock.mjs';

import {
  CLAIM_MARKER, EPISODE_MARKER, PROGRESS_HEADING, parseProgressLines, withSection,
} from './work-item.mjs';

export const HEARTBEAT_MARKER = '<!-- claudinite-heartbeat -->';

// Comfortably inside the executing leash (60m), so a live holder is never
// reclaimed on a single missed beat: it takes four in a row.
export const HEARTBEAT_MS = 15 * 60e3;

export const heartbeatComment = ({ executor, at, minutes }) =>
  `${HEARTBEAT_MARKER}\nStill working: executor \`${executor}\`, ${minutes} minute(s) in, at ${at}.`;

// When the current holder last said anything — the newest live claim or heartbeat.
// A struck comment is not a signal: it says its author let the item go.
export function lastLivenessAt(comments = []) {
  const live = comments.filter((c) => {
    const body = c.body ?? '';
    if (body.includes(EPISODE_MARKER)) return false;
    return body.includes(CLAIM_MARKER) || body.includes(HEARTBEAT_MARKER);
  });
  const times = live.map((c) => new Date(c.created_at ?? 0).getTime()).filter((t) => t > 0);
  return times.length ? new Date(Math.max(...times)).toISOString() : null;
}

// The timer the beat hangs on. A seam for the same reason the clock beside it is
// one: a harness that runs a work step in virtual minutes has no wall clock for a
// real interval to fire against, so the beats would be missing from exactly the
// timeline the executing leash is reading.
export const realTimers = Object.freeze({
  setInterval: (fn, ms) => setInterval(fn, ms),
  clearInterval: (id) => clearInterval(id),
});

// Run `work` while beating. The beat is FAIL-SOFT — a comment that does not post
// must never sink a run that is otherwise fine — but never silent: a run whose
// heartbeat failed is one the leash may reclaim underneath it, and the log line is
// the only way to tell that from a run that simply finished quickly.
export async function withHeartbeat(work, { beat, intervalMs = HEARTBEAT_MS, log = () => {}, timers = realTimers }) {
  if (!beat || !(intervalMs > 0)) return work();
  const startedAt = nowMs();
  let beats = 0;
  const timer = timers.setInterval(() => {
    const minutes = Math.round((nowMs() - startedAt) / 60e3);
    Promise.resolve()
      .then(() => beat(minutes))
      .then(() => { beats += 1; })
      .catch((e) => log(`! heartbeat ${beats + 1} did not post (${e?.message ?? e}) — the leash may reclaim this item mid-work`));
  }, intervalMs);
  // `unref` so a beat pending at exit cannot hold the process open past its work.
  timer?.unref?.();
  try {
    return await work();
  } finally {
    timers.clearInterval(timer);
    const minutes = Math.round((nowMs() - startedAt) / 60e3);
    if (beats) log(`- work step ran ${minutes} minute(s) and beat ${beats} time(s)`);
  }
}

// --- the agent phase's beat -----------------------------------------------------

// The executor's beat above stops at the hand-off: its process exits, and an agent
// session then holds the item for as long as its own work takes. Nothing beat there,
// so the agent leash had only the issue's `updated_at` to read — the very clock this
// file exists to stop trusting.
//
// The session cannot beat the way the executor does. It has no process of its own to
// hang a timer on, and a scheduled wake reaches it between tool results rather than
// during one, so a beat that must fire inside a long call cannot be promised. What it
// can promise is a beat at each checkpoint its own work already has. Hence the
// interval below is a CEILING the session is asked to stay under, not a timer.
export const AGENT_BEAT_MS = 45 * 60e3;

// Carries the same marker as the executor's beat, so `lastLivenessAt` counts an agent
// beat as the holder's own signal without knowing which phase wrote it.
export const agentBeatComment = ({ session, at, note }) =>
  `${HEARTBEAT_MARKER}\nStill working${session ? `: ${session}` : ''} — ${note}, at ${at}.`;

// One progress line, appended to the item body's own `### Progress` section.
//
// APPENDED, not replaced: the body is the only surface a run can grow in place,
// because the GitHub toolset a session has offers comment creation and no comment
// edit. So the body carries the account and the beats carry the trail — the same
// split the standing trackers use, arrived at from the opposite direction.
export const withProgress = (body, line) =>
  withSection(body, PROGRESS_HEADING, [...parseProgressLines(body), line]);

// WHEN THE WORK LAST MOVED, as distinct from when the holder last spoke.
//
// A beat resets the leash, so a session that beats punctually while wedged would
// never be reclaimed — the signal degrades from "work is happening" to "a process is
// alive", which is the failure the leash exists to catch. The beat already carries
// what separates them: its note is the progress (`9/15 groups triaged`), so a run of
// beats all saying the same thing is a wedged run, however punctual.
//
// Returns when the note last CHANGED — the oldest beat of the trailing run that all
// carry the newest one's note — or null when the item has no beats at all, which is
// the caller's signal to judge it the old way rather than to call it dead.
export function lastProgressAt(comments = []) {
  const beats = comments
    .filter((c) => (c.body ?? '').includes(HEARTBEAT_MARKER) && !(c.body ?? '').includes(EPISODE_MARKER))
    .map((c) => ({ at: new Date(c.created_at ?? 0).getTime(), note: beatNote(c.body ?? '') }))
    .filter((b) => b.at > 0)
    .sort((a, b) => a.at - b.at);
  if (!beats.length) return null;
  const newest = beats[beats.length - 1].note;
  let i = beats.length - 1;
  while (i > 0 && beats[i - 1].note === newest) i -= 1;
  return new Date(beats[i].at).toISOString();
}

// The part of a beat that says where the work got to. Read off the comment rather
// than kept beside it: the beat a session posts through its own GitHub tools is the
// only copy, so the note has to survive the round trip through the rendered body.
const beatNote = (body) => {
  const line = body.split('\n').find((l) => l.startsWith('Still working')) ?? '';
  return (line.match(/ — (.*), at [^,]*\.$/)?.[1] ?? line).trim();
};

// THE CLOCK PORT. Reading "now" is an edge to the world exactly like a REST call
// is: it makes a run's answer depend on something outside its inputs. Every
// module under `src/` that needs the current instant asks here, so a simulator
// can drive a whole run at a chosen instant by replacing this one implementation
// and nothing else changes hands.
//
// Parsing a timestamp is NOT a clock read — `new Date(iso)` over a string a
// caller supplied is arithmetic, stays where it is used, and is deliberately
// outside what this port covers.

// What "now" currently reads from. The wall clock in production, and whatever a
// simulator installed while it is driving a run.
let readMs = () => Date.now();

// The current instant, as a Date. The one place `new Date()` is called with no
// argument anywhere under `src/`.
export const now = () => new Date(readMs());

// The current instant in epoch milliseconds — for durations and unique suffixes,
// where a Date object would only be unwrapped again.
export const nowMs = () => readMs();

// The current instant as the ISO-8601 string the queue's records are written in.
export const nowIso = () => new Date(readMs()).toISOString();

// Replace the reading, and return the undo. This is the "replacing this one
// implementation" the header promises: a harness running the engine against a
// virtual clock installs its own instant here, and every `src/` module that asks
// for the time — the claim comment's stamp, a `Woken:` field, a minted branch's
// date — answers in that world rather than in this year.
//
// Deliberately a whole-process switch rather than a threaded argument: the point
// of a port is that a caller says what it needs and not where it comes from, and
// threading an instant through every module that reads one would put the clock
// back into every signature this module exists to keep it out of. Production
// never calls it; the undo is what keeps one harness's instant out of the next.
export function installClock(read) {
  const previous = readMs;
  readMs = read;
  return () => { readMs = previous; };
}

// THE FAKE CLOCK — virtual time and the ordered event queue every other fake
// module schedules on.
//
// It stands in for `src/world/clock.mjs`, so `port` carries exactly that
// module's names and nothing else; everything a scenario drives the clock WITH
// hangs off the harness object beside it. That split is what lets the parity
// guard compare key sets — a port that also carried `runUntil` could never be
// compared against the real one — and it is the shape every module in this
// folder takes.
//
// Time moves only when an event fires or a scenario advances it. There is no
// wall clock here at all — no `setTimeout`, no `Date.now()` — so a run is
// deterministic and a scenario spanning a fortnight costs microseconds.
//
// ORDERING IS TOTAL: strictly by instant, FIFO within a tie. Two events booked
// for the same instant fire in the order they were booked, which is what lets a
// scenario WRITE a race rather than hope for one.
//
// AN EVENT MAY WAIT FOR A LATER ONE, which is why the loop below is a pump rather
// than `await ev.fn()` per event. The code this harness drives is straight-line
// async — an executor run awaits its work step, and that step takes virtual
// minutes — so an event awaited to completion would be waiting on an event the
// queue can no longer reach. Instead an event is STARTED, and the clock advances
// only once every started event has either finished or parked on `sleep`.
// `running` counts the started, `waiting` the parked, and equality is quiescence:
// nothing is mid-step, so the next instant is safe to fire.
//
// `sleep` is therefore the only legal way to wait for virtual time from inside an
// event. A real timer would never fire at all here, and a promise resolved from
// outside the accounting is invisible to the pump — which would call the world
// quiet while a run was still mid-step.

const at_ = (when) => (typeof when === 'number' ? when : Date.parse(when));

export const MINUTE = 60_000;
export const HOUR = 60 * MINUTE;
export const DAY = 24 * HOUR;

// How many macrotask turns the pump spends waiting for quiescence before it calls
// the world wedged. Generous — a cold dynamic import takes a few — and finite,
// because the alternative to this error is a test that hangs with no output.
const SETTLE_TURNS = 5000;

export function makeClock({ start = '2026-08-12T00:00:00Z' } = {}) {
  let t = at_(start);
  let seq = 0;
  const queue = [];
  let running = 0;
  let waiting = 0;
  const failures = [];

  const port = {
    now: () => new Date(t),
    nowMs: () => t,
    nowIso: () => new Date(t).toISOString(),
    // The real port's escape hatch, which this one has no use for: installing a
    // reading of "now" into the clock that IS the reading changes nothing. It is
    // here so the two ports stay comparable, and so a caller holding either can
    // call it without asking which it holds.
    installClock: () => () => {},
  };

  // Book `fn` at an absolute instant. An instant already past is booked at the
  // current one rather than dropped: a fake that silently "missed" it would be
  // modelling a platform behaviour nobody asked for.
  const at = (when, fn) => { queue.push({ t: Math.max(at_(when), t), seq: seq++, fn }); return harness; };
  const after = (deltaMs, fn) => at(t + deltaMs, fn);

  // Wait `ms` of VIRTUAL time from inside a running event. The wait is declared to
  // the pump, so the clock knows this event is parked rather than mid-step, and it
  // resumes as an ordinary booked event — a sleeper takes its turn in the same
  // total order as everything else.
  const sleep = (ms) => new Promise((resolve) => {
    waiting += 1;
    at(t + Math.max(0, ms), () => { waiting -= 1; resolve(); });
  });

  // Wait for something that is not virtual time but cannot settle until it
  // advances — a queued workflow run waiting for the one holding its concurrency
  // group. Declared to the pump the same way `sleep` is, because the alternative
  // is a world that never reaches quiescence and so never advances the clock the
  // waiter is waiting for.
  const park = (promise) => {
    waiting += 1;
    return Promise.resolve(promise).then(
      (v) => { waiting -= 1; return v; },
      (e) => { waiting -= 1; throw e; },
    );
  };

  // Start an event without waiting for it. A rejection is collected rather than
  // thrown here: it belongs to the scenario that ran the segment, not to whichever
  // instant happened to be current when it surfaced.
  const fire = (fn) => {
    running += 1;
    Promise.resolve().then(fn).then(
      () => { running -= 1; },
      (e) => { running -= 1; failures.push(e); },
    );
  };

  // Let every started event run until it finishes or parks. One macrotask turn
  // drains the whole microtask chain behind it, so ordinary async code — a promise
  // chain, an awaited fake API call, a cached dynamic import — settles in a turn or
  // two; only virtual time takes more.
  // Quiescence is "no started event is mid-step", which is `running <= waiting`
  // rather than equality: a scenario may sleep or park from OUTSIDE any event —
  // starting a run by hand and letting its body take virtual minutes — and such a
  // waiter is parked without ever having been counted as running.
  const settle = async () => {
    for (let i = 0; i < SETTLE_TURNS; i += 1) {
      await new Promise((r) => setImmediate(r));
      if (running <= waiting) return;
    }
    throw new Error(`the fake world did not settle: ${running - waiting} event(s) are still mid-step`
      + ' — something is waiting on a promise that virtual time can never resolve');
  };

  // Fire every event strictly before `to`, then park the clock AT `to`. Events
  // beyond it SURVIVE for a later segment — a scenario runs in phases to assert
  // a mid-state, and a queue emptied at each boundary would lose them.
  const runUntil = async (to) => {
    const end = at_(to);
    for (;;) {
      await settle();
      queue.sort((a, b) => a.t - b.t || a.seq - b.seq);
      if (!queue.length || queue[0].t >= end) break;
      const ev = queue.shift();
      t = ev.t;
      fire(ev.fn);
    }
    await settle();
    t = end;
    if (failures.length) throw failures[0];
    return harness;
  };

  const harness = {
    port,
    at,
    after,
    sleep,
    park,
    runUntil,
    // The instant, for a scenario computing one rather than reading it back off
    // an artifact.
    ms: () => t,
    iso: () => port.nowIso(),
    // How much has not fired yet: what a scenario asserting "nothing is left"
    // reads, instead of reaching into the array.
    pending: () => queue.length,
    // Anything a started event threw. `runUntil` rethrows the first, so this is
    // for a scenario that wants to look without ending its segment.
    failures: () => failures,

    // VIRTUAL TIMERS, in the `setInterval`/`clearInterval` shape the engine's
    // heartbeat hangs its beat on. A real timer inside a work step of virtual
    // minutes never fires at all, so the beats would be missing from exactly the
    // timeline the executing leash reads.
    timers: () => {
      let nextId = 0;
      const live = new Set();
      const setIntervalV = (fn, ms) => {
        const id = (nextId += 1);
        live.add(id);
        const tick = () => {
          if (!live.has(id)) return;
          fn();
          at(t + ms, tick);
        };
        at(t + ms, tick);
        return id;
      };
      return { setInterval: setIntervalV, clearInterval: (id) => live.delete(id) };
    },
  };
  return harness;
}

